/** Latitude and longitude to a point in the viewBox. */
export function project(lat: number, lon: number): { x: number; y: number } {
  return {
    x: PADDING + (lon - MIN_LON) * X_SCALE * SCALE,
    y: PADDING + (MAX_LAT - lat) * SCALE,
  };
}
